import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.NoSuchElementException;

public class SolutionTest {
    private interface Checked { void run(); }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expect(Class<? extends Throwable> type, Checked action) {
        try {
            action.run();
            throw new AssertionError("Expected " + type.getSimpleName());
        } catch (Throwable actual) {
            if (!type.isInstance(actual)) {
                throw new AssertionError("Expected " + type.getSimpleName() + " but got " + actual, actual);
            }
        }
    }

    private static Solution.Product product(int id, String name, String category, long price) {
        return new Solution.Product(id, name, category, price);
    }

    private static void assertIds(List<Solution.Product> products, int... ids) {
        check(products.size() == ids.length, "wrong list size");
        for (int i = 0; i < ids.length; i++) {
            check(products.get(i).getId() == ids[i], "wrong ID at index " + i);
        }
    }

    public static void main(String[] args) {
        Solution.Product p1 = product(1, "Pen", "Office", 125);
        Solution.Product p2 = product(2, "Book", "Office", 999);
        Solution.Product p3 = product(3, "Lamp", "Home", 0);
        check(p1.getId() == 1, "wrong product ID");
        check("Pen".equals(p1.getName()), "wrong name");
        check("Office".equals(p1.getCategory()), "wrong category");
        check(p1.getPriceCents() == 125, "wrong price");

        expect(IllegalArgumentException.class, () -> product(0, "A", "B", 0));
        expect(IllegalArgumentException.class, () -> product(-1, "A", "B", 0));
        expect(IllegalArgumentException.class, () -> product(1, null, "B", 0));
        expect(IllegalArgumentException.class, () -> product(1, " ", "B", 0));
        expect(IllegalArgumentException.class, () -> product(1, "A", null, 0));
        expect(IllegalArgumentException.class, () -> product(1, "A", "\t", 0));
        expect(IllegalArgumentException.class, () -> product(1, "A", "B", -1));

        List<Solution.Product> emptyCreated = Solution.create(Collections.<Solution.Product>emptyList(), p2);
        assertIds(emptyCreated, 2);
        expect(UnsupportedOperationException.class, () -> emptyCreated.add(p1));

        ArrayList<Solution.Product> input = new ArrayList<Solution.Product>();
        input.add(p3);
        input.add(p1);
        List<Solution.Product> created = Solution.create(input, p2);
        assertIds(created, 1, 2, 3);
        check(input.size() == 2 && input.get(0) == p3 && input.get(1) == p1, "create mutated input");
        input.clear();
        assertIds(created, 1, 2, 3);
        expect(UnsupportedOperationException.class, () -> created.remove(0));
        expect(IllegalStateException.class, () -> Solution.create(created, product(2, "Other", "Other", 1)));

        Solution.Product read = Solution.read(created, 3);
        check(read == p3, "read returned wrong product");
        expect(NoSuchElementException.class, () -> Solution.read(created, 99));

        Solution.Product replacement = product(2, "Notebook", "School", 450);
        List<Solution.Product> updated = Solution.update(Arrays.asList(p3, p2, p1), replacement);
        assertIds(updated, 1, 2, 3);
        check(updated.get(1) == replacement, "replacement not installed");
        check("Notebook".equals(updated.get(1).getName()), "replacement data lost");
        expect(UnsupportedOperationException.class, () -> updated.set(0, p2));
        expect(NoSuchElementException.class, () -> Solution.update(created, product(8, "X", "Y", 0)));

        ArrayList<Solution.Product> deleteInput = new ArrayList<Solution.Product>(Arrays.asList(p3, p1, p2));
        List<Solution.Product> deleted = Solution.delete(deleteInput, 2);
        assertIds(deleted, 1, 3);
        assertIds(deleteInput, 3, 1, 2);
        deleteInput.set(0, p2);
        assertIds(deleted, 1, 3);
        expect(UnsupportedOperationException.class, () -> deleted.clear());
        expect(NoSuchElementException.class, () -> Solution.delete(deleted, 2));

        expect(NullPointerException.class, () -> Solution.create(null, p1));
        expect(NullPointerException.class, () -> Solution.create(created, null));
        expect(NullPointerException.class, () -> Solution.read(null, 1));
        expect(NullPointerException.class, () -> Solution.update(null, p1));
        expect(NullPointerException.class, () -> Solution.update(created, null));
        expect(NullPointerException.class, () -> Solution.delete(null, 1));

        List<Solution.Product> withNull = Arrays.asList(p1, null);
        expect(NullPointerException.class, () -> Solution.create(withNull, p2));
        expect(NullPointerException.class, () -> Solution.read(withNull, 1));
        expect(NullPointerException.class, () -> Solution.update(withNull, p2));
        expect(NullPointerException.class, () -> Solution.delete(withNull, 1));

        List<Solution.Product> emptyDeletedSource = Collections.emptyList();
        expect(NoSuchElementException.class, () -> Solution.delete(emptyDeletedSource, 1));
        expect(NoSuchElementException.class, () -> Solution.update(emptyDeletedSource, p1));
        expect(NoSuchElementException.class, () -> Solution.read(emptyDeletedSource, 1));

        int modifiers = Solution.Product.class.getModifiers();
        check(java.lang.reflect.Modifier.isPublic(modifiers), "Product must be public");
        check(java.lang.reflect.Modifier.isStatic(modifiers), "Product must be static");
        check(java.lang.reflect.Modifier.isFinal(modifiers), "Product must be final");
    }
}

